"use strict";
// Loads its parts with a computed specifier (R1.2): a Node island. Its
// functions report exactly what arrives: argument counts, explicit
// undefined, key presence of undefined-valued fields, arrays.
const { createRequire } = require("node:module");
const util = createRequire(__filename)(["node", "util"].join(":"));

function describeValue(v) {
  if (v === undefined) return "undefined";
  if (Array.isArray(v)) return `array(${v.length}:${v.map(describeValue).join(",")})`;
  if (v !== null && typeof v === "object")
    return `{${Object.keys(v)
      .map((k) => `${k}=${describeValue(v[k])}`)
      .join(",")}}`;
  return JSON.stringify(v);
}

exports.probe = function probe(a, b, c, d) {
  return [
    `len=${arguments.length}`,
    `a=${describeValue(a)}`,
    `b=${describeValue(b)}`,
    `in=${b !== undefined && b !== null && "nodeVersion" in b}`,
    `own=${b !== undefined && b !== null && Object.prototype.hasOwnProperty.call(b, "nodeVersion")}`,
    `c=${describeValue(c)}`,
    `d=${describeValue(d)}`,
  ].join(" ");
};

exports.defaults = function defaults(x = "dx", y = "dy", ...rest) {
  return `${x}|${y}|rest=${rest.length}|len=${arguments.length}`;
};

exports.version = function version(path, fallback = "unused", config = {}, meta, available) {
  const wanted = config.nodeVersion ?? (meta && meta.nodeVersion) ?? null;
  const list = Array.isArray(available) ? available : [];
  if (wanted === null) {
    const latest = Math.max(...list);
    return `${path}: ${list.includes(latest) ? `${latest}.x` : fallback}`;
  }
  return `${path}: ${wanted}`;
};

exports.inspect = (v) => util.inspect(v);

// A version-lookup helper's shape: async, defaults for omitted
// arguments, engines.node from the package.json in `dir` first.
exports.nodeVersionFor = async function nodeVersionFor(
  dir,
  fallback = "unused",
  config = {},
  meta = {},
  available = [16],
) {
  const fs = require("node:fs/promises");
  const path = require("node:path");
  let engines = null;
  try {
    engines = JSON.parse(await fs.readFile(path.join(dir, "package.json"), "utf8")).engines ?? null;
  } catch {
    engines = null;
  }
  if (engines && engines.node) return `engines:${engines.node}:${Math.max(...available)}`;
  const configured = config.nodeVersion || fallback;
  if (configured === "unused") throw new Error(`Found invalid or discontinued Node.js Version: "${configured}"`);
  return `configured:${configured}:${meta.isDev === true}`;
};

exports.cwd = () => process.cwd();
exports.envValue = (name) => process.env[name];

// A native plain object is a plain object here (jose's isObject).
exports.plain = (v) =>
  [
    Object.getPrototypeOf(v) === Object.prototype,
    Object.prototype.toString.call(v),
    Object.getPrototypeOf(Object.getPrototypeOf(v)) === null,
  ].join(" ");
